mapper.select:
SELECT /* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.select.selectProdSubscrInfo - 상품 구독 정보 조회 */ SAAS_PRDCT_ID /* SAAS제품아이디 */ , INST_USER_INTG_ID /* 기관사용자통합아이디 */ , INST_USER_SE_CD /* 기관사용자구분코드 */ , PRDSBSC_SN /* 제품구독일련번호 */ , PRDSBSC_STTS_CD /* 제품구독상태코드 */ , USCM.SF_COMM_CD_NM(PRDSBSC_STTS_CD) AS PRDSBSC_STTS_NM /* 제품구독상태명 */ , PRDSBSC_BGNG_YMD /* 제품구독시작일자 */ , PRDSBSC_END_YMD /* 제품구독종료일자 */ , FRST_CRT_DT /* 최초생성일시 */ , FRST_CRT_PRCR_ID /* 최초생성처리자아이디 */ , LAST_CHG_DT /* 최종변경일시 */ , LAST_CHG_PRCR_ID /* 최종변경처리자아이디 */ FROM USCM.TBCM_PRDSBSC_L WHERE 1 = 1
AND INST_USER_INTG_ID=#{instUserIntgId}
AND SAAS_PRDCT_ID=#{saasPrdctId}
AND INST_USER_SE_CD=#{instUserSeCd}
ORDER BY PRDSBSC_SN DESC LIMIT 1

mapper.update:
/* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.insert.insertProdSubscrReq - 상품 구독 요청 (구독내역) */

	SELECT
		COALESCE(MAX(PRDSBSC_SN) + 1, 1)
	FROM USCM.TBCM_PRDSBSC_L
	WHERE SAAS_PRDCT_ID  = #{saasPrdctId}
	AND INST_USER_INTG_ID = #{instUserIntgId}
	AND INST_USER_SE_CD = #{instUserSeCd}

INSERT INTO USCM.TBCM_PRDSBSC_L (
	SAAS_PRDCT_ID                         	/* SAAS제품아이디 */
	, INST_USER_INTG_ID                     /* 기관사용자통합아이디 */
	, INST_USER_SE_CD                       /* 기관사용자구분코드 */
	, PRDSBSC_SN                         	/* 제품구독일련번호 */
	, PRDSBSC_STTS_CD                       /* 제품구독상태코드 */
	, PRDSBSC_BGNG_YMD                      /* 제품구독시작일자 */
	, PRDSBSC_END_YMD                       /* 제품구독종료일자 */
	, FRST_CRT_DT                         	/* 최초생성일시 */
	, FRST_CRT_PRCR_ID                      /* 최초생성처리자아이디 */
	, LAST_CHG_DT                         	/* 최종변경일시 */
	, LAST_CHG_PRCR_ID                      /* 최종변경처리자아이디 */
) VALUES (
	#{saasPrdctId}
	, #{instUserIntgId}
	, #{instUserSeCd}
	, #{prdsbscSn}
	, #{prdsbscSttsCd}
	, ''
	, ''
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{accountId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{accountId}
)

/* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.insert.insertProdSubscrHistoryReq - 상품 구독 요청 (구독이력) */

	SELECT
		COALESCE(MAX(PRDSBSC_HSTRY_SN)+1, 1)
	FROM USCM.TBCM_PRDSBSC_H 
	WHERE SAAS_PRDCT_ID   = #{saasPrdctId}
	AND INST_USER_INTG_ID = #{instUserIntgId}
	AND INST_USER_SE_CD = #{instUserSeCd}

INSERT INTO USCM.TBCM_PRDSBSC_H (
	SAAS_PRDCT_ID        /* SAAS제품아이디 */
	, INST_USER_INTG_ID    /* 기관사용자통합아이디 */
	, INST_USER_SE_CD      /* 기관사용자구분코드 */
	, PRDSBSC_SN           /* 제품구독일련번호 */
	, PRDSBSC_HSTRY_SN     /* 제품구독이력일련번호 */
	, PRDSBSC_STTS_CD      /* 제품구독상태코드 */
	, PRDSBSC_BGNG_YMD     /* 제품구독시작일자 */
	, PRDSBSC_END_YMD      /* 제품구독종료일자 */
	, FRST_CRT_DT          /* 최초생성일시 */
	, FRST_CRT_PRCR_ID     /* 최초생성처리자아이디 */
	, LAST_CHG_DT          /* 최종변경일시 */
	, LAST_CHG_PRCR_ID     /* 최종변경처리자아이디 */
) VALUES (
	#{saasPrdctId} 
	, #{instUserIntgId} 
	, #{instUserSeCd} 
	, #{prdsbscSn}
	, #{prdsbscHstrySn}
	, #{prdsbscSttsCd}
	, #{prdsbscBgngYmd}
	, #{prdsbscEndYmd}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
	, #{accountId} 
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS') 
	, #{accountId}
)

UPDATE /* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.update.updateProdSubscrReq - 상품 구독 취소 요청 */
	USCM.TBCM_PRDSBSC_L
SET
	PRDSBSC_STTS_CD= #{prdsbscSttsCd}	                             /* 제품구독일련번호 */
	, LAST_CHG_DT = TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')    /* 최종변경일시 */
	, LAST_CHG_PRCR_ID = #{accountId}                                /* 최종변경처리자아이디 */
WHERE 
	PRDSBSC_SN = #{prdsbscSn}

		AND SAAS_PRDCT_ID = #{saasPrdctId}


		AND INST_USER_INTG_ID = #{instUserIntgId}


		AND INST_USER_SE_CD = #{instUserSeCd}

mapper.select:
SELECT /* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.select.existProdReviewInfo - 리뷰 조회 - 리뷰 존재 여부 확인 */
	COUNT(*)
FROM USCM.TBCM_SAAS_PRDCT_EVL_L
WHERE 1=1 

	AND EVLTR_ID = #{evltrId}


	AND SAAS_PRDCT_ID = #{saasPrdctId}

mapper.update:
/* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.insert.insertProdReview - 상품 후기 등록 요청 */
INSERT INTO USCM.TBCM_SAAS_PRDCT_EVL_L (
	SAAS_PRDCT_ID                              /* saas제품아이디    */
	, EVLTR_ID                                 /* 평가자아이디       */
	, SAAS_PRDCT_EVL_SCR                       /* saas제품평가점수   */
	, SAAS_PRDCT_EVL_CN                        /* saas제품평가내용   */
	, FRST_CRT_DT                              /* 최초생성일시       */
	, FRST_CRT_PRCR_ID                         /* 최초생성처리자아이디  */
	, LAST_CHG_DT                              /* 최종변경일시       */
	, LAST_CHG_PRCR_ID                         /* 최종변경처리자아이디  */
) VALUES (
	#{saasPrdctId}
	, #{evltrId}
	, #{saasPrdctEvlScr}
	, #{saasPrdctEvlCn}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{evltrId}
	, TO_CHAR(CURRENT_TIMESTAMP,'YYYYMMDDHH24MISS')
	, #{evltrId}
)

DELETE /* SQL_ID: ci.sc.cp.cpm.mapper.ProdMapper.delete.deleteProdReview - 상품 후기 삭제 요청 */
FROM USCM.TBCM_SAAS_PRDCT_EVL_L
WHERE EVLTR_ID = #{evltrId}
AND SAAS_PRDCT_ID = #{saasPrdctId}
